input.command:
S=$PWD/.claude/skills/content-search-audit && rtk proxy cat $S/references/worked-review.md $S/references/judgment-and-advice.md $S/references/quote-verification.md $S/references/report-contract.md; rtk proxy node -e '
const r=JSON.parse(require("fs").readFileSync(process.argv[1]));
for(const x of r.rules) console.log(JSON.stringify({id:x.id,dim:x.dimension,ev:x.requiredEvidence||x.requiredEvidenceKinds,mode:x.mode||x.evaluation,app:x.applicability,title:x.title||x.name}));
console.log(Object.keys(r), Object.keys(r.rules[0]));' $S/rules/core.json

S=$PWD/.claude/skills/content-search-audit && rtk proxy node -e '
const r=JSON.parse(require("fs").readFileSync(process.argv[1]));
for(const x of r.rules) console.log(x.ruleId,"|",x.requiredEvidence.join(","),"|",x.procedure);' $S/rules/core.json; rtk proxy node $S/scripts/audit.mjs methods; rtk proxy cat $S/scripts/examples/worked-review.mjs $S/references/measurement.md

R=$PWD; S=$R/.claude/skills/content-search-audit; mkdir -p $R/audits/content-search/work; rtk proxy grep -n "blocked\|allowedOrigins" $S/scripts/lib/run.mjs | head -30; rtk proxy node -e '
const fs=require("fs"),R=process.argv[1];
const files=fs.readdirSync(R+"/targets").sort();
const inputs=files.map(f=>({path:R+"/targets/"+f,source:"supplied-dossier",locale:(f.startsWith("05")||f.startsWith("07"))?"vi":"en"}));
inputs.push({uri:"https://docs.example.invalid/guide.pdf",source:"declared-url",type:"pdf"});
inputs.push({uri:"https://docs.example.invalid/video",source:"declared-url",type:"video"});
fs.writeFileSync(R+"/audits/content-search/work/config.json",JSON.stringify({inputs,localRoots:[R+"/targets"],inventoryComplete:true,mode:"full"},null,2));' $R; rtk proxy node $S/scripts/audit.mjs start $R/audits/content-search/work/config.json $R/audits/content-search/run-01-start; ls $R/audits/content-search/run-01-start

D=$PWD/audits/content-search/run-01-start; rtk proxy node -e '
const fs=require("fs"),D=process.argv[1];
const L=f=>fs.readFileSync(D+"/"+f,"utf8").trim().split("\n").map(JSON.parse);
const inv=L("inventory.jsonl"),ev=L("evidence.jsonl"),ch=L("checks.jsonl");
console.log(JSON.stringify(inv[0],null,1));console.log(JSON.stringify(inv.find(i=>i.uri&&i.uri.startsWith("http"))||inv[11],null,1));
for(const i of inv)console.log(i.itemId.slice(0,8),i.uri||i.path,i.status||i.state);
for(const e of ev)console.log(JSON.stringify({...e,value:String(JSON.stringify(e.value)).slice(0,80)}));
const s={};for(const c of ch){s[c.ruleId+":"+c.status]=(s[c.ruleId+":"+c.status]||0)+1}console.log(s);console.log(JSON.stringify(ch[4]),JSON.stringify(ch.at(-1)));
' $D; cat $D/delivery-summary.md; ls $D/evidence; cat $D/findings.json | head -40

R=$PWD; S=$R/.claude/skills/content-search-audit; A=$R/audits/content-search; W=$A/work
rtk proxy node $S/scripts/audit.mjs validate $A/run-02-reviewed > $W/validation-run-02.json; echo validate_exit=$?
rtk proxy node -e '
const fs=require("fs"),[A,W,R]=process.argv.slice(1);
const v=JSON.parse(fs.readFileSync(W+"/validation-run-02.json"));
const c=v.coverage;console.log(JSON.stringify({valid:v.valid,completionAllowed:v.completionAllowed,errors:v.errors,total:c.total,audited:c.audited,states:c.states,dims:c.dimensions,lim:c.limitations}));
const ch=fs.readFileSync(A+"/run-02-reviewed/checks.jsonl","utf8").trim().split("\n").map(JSON.parse);
const inv=fs.readFileSync(A+"/run-02-reviewed/inventory.jsonl","utf8").trim().split("\n").map(JSON.parse);
const nm=Object.fromEntries(inv.map(i=>[i.itemId,(i.path||i.uri).split("/").pop()]));
for(const x of ch.filter(x=>x.status!=="unknown"))console.log(nm[x.itemId],x.ruleId,x.status);
for(const x of ch.filter(x=>x.ruleId==="seo-response"))console.log(nm[x.itemId],x.status,x.reason);
// study options
const crypto=require("crypto");const t=fs.readFileSync(R+"/targets/08-study.md","utf8");const lines=t.split("\n");
fs.writeFileSync(W+"/report-options.json",JSON.stringify({studySources:[{sourceId:"study-08-synthetic-api-panel",kind:"historical-study",locator:"targets/08-study.md",sourceText:t,sourceHash:crypto.createHash("sha256").update(t).digest("hex"),synthetic:true,
scope:{population:"100 responses from a synthetic English API panel (as stated by the dossier)",interface:"API (synthetic), English",collectionWindow:"2024-02-01 through 2024-02-14",publication:"2026-11-01",market:"unknown",engine:"unknown"},
limitations:["Synthetic fixture aggregate; no response-level records, prompts, engine or model were supplied","Historical collection window; does not establish the current rate, per the source itself","API panel output is not consumer-UI evidence and is not a measurement of any brand","Study authenticity and sampling quality are not verified"],
passages:[{startLine:4,endLine:4,quote:lines[3]},{startLine:5,endLine:5,quote:lines[4]}]}]},null,2));
' $A $W $R
mkdir $A/run-03-report && cd $A/run-02-reviewed && rtk proxy cp -R checks.jsonl config.json evidence evidence.jsonl findings.json inventory.jsonl run.json $A/run-03-report/ && cd $R && ls $A/run-02-reviewed && rtk proxy node $S/scripts/audit.mjs render-with-measurements $A/run-03-report $W/report-options.json > $W/render-result.json; echo render_exit=$?; rtk proxy tail -c 400 $W/render-result.json; ls $A/run-03-report; cat $A/run-03-report/delivery-summary.md; rtk proxy node $S/scripts/audit.mjs validate $A/run-03-report > $W/validation-run-03.json; echo v3=$?; rtk proxy node -e 'const v=JSON.parse(require("fs").readFileSync(process.argv[1]));console.log(v.valid,v.completionAllowed,v.coverage.total,v.coverage.audited,JSON.stringify(v.coverage.states),v.errors)' $W/validation-run-03.json
